    __m256i vd = _mm256_set1_epi32(0xa54ff53a);
    __m256i ve = _mm256_set1_epi32(0x510e527f);
    __m256i vf = _mm256_set1_epi32(0x9b05688c);
    __m256i vg = _mm256_set1_epi32(0x1f83d9ab);
    __m256i vh = _mm256_set1_epi32(0x5be0cd19);

