static inline void compress(uint32_t s[8], const uint32_t wk[64]){
    uint32_t a=s[0],b=s[1],c=s[2],d=s[3],e=s[4],f=s[5],g=s[6],h=s[7];
    for (int i=0;i<64;i++){
        uint32_t t1 = h + S1(e) + CH(e,f,g) + wk[i];
        uint32_t t2 = S0(a) + MAJ(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    s[0]+=a; s[1]+=b; s[2]+=c; s[3]+=d; s[4]+=e; s[5]+=f; s[6]+=g; s[7]+=h;
}

void sha256_fast(const uint8_t* data, size_t len, uint8_t out[32]){
    uint32_t s[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len / 64;
    size_t i = 0;
    __m256i vK[64];
    for (int j=0;j<64;j++) vK[j] = _mm256_set1_epi32(K[j]);
    // process 8 blocks at a time
    for (; i + 8 <= nblocks; i += 8){
        __m256i w[64];
        for (int j=0;j<16;j++) w[j] = load8(data + i*64, j);
        for (int j=16;j<64;j++){
            __m256i s0 = _mm256_xor_si256(_mm256_xor_si256(rotr(w[j-15],7),rotr(w[j-15],18)),_mm256_srli_epi32(w[j-15],3));
            __m256i s1 = _mm256_xor_si256(_mm256_xor_si256(rotr(w[j-2],17),rotr(w[j-2],19)),_mm256_srli_epi32(w[j-2],10));
            w[j] = _mm256_add_epi32(_mm256_add_epi32(_mm256_add_epi32(w[j-16],s0),w[j-7]),s1);
        }
        // add K to get WK, store transposed
        uint32_t wk[64][8];
        for (int j=0;j<64;j++){
            __m256i t = _mm256_add_epi32(w[j], vK[j]);
            _mm256_storeu_si256((__m256i*)wk[j], t);
        }
        for (int b=0;b<8;b++){
            uint32_t wkb[64];
            for (int j=0;j<64;j++) wkb[j] = wk[j][b];
            compress(s, wkb);
        }
    }
    // remaining blocks scalar
    for (; i < nblocks; i++){
        uint32_t w[64];
        const uint8_t* blk = data + i*64;
        for (int j=0;j<16;j++) w[j] = ((uint32_t)blk[j*4]<<24)|((uint32_t)blk[j*4+1]<<16)|((uint32_t)blk[j*4+2]<<8)|blk[j*4+3];
        for (int j=16;j<64;j++){
            uint32_t s0 = ROTR(w[j-15],7)^ROTR(w[j-15],18)^(w[j-15]>>3);
            uint32_t s1 = ROTR(w[j-2],17)^ROTR(w[j-2],19)^(w[j-2]>>10);
            w[j] = w[j-16]+s0+w[j-7]+s1;
        }
        uint32_t wk[64];
        for (int j=0;j<64;j++) wk[j] = w[j] + K[j];
        compress(s, wk);
    }
    // padding
    uint8_t buf[128];
    size_t rem = len - i*64;
    memcpy(buf, data + i*64, rem);
    buf[rem] = 0x80;
    size_t padlen;
    if (rem < 56){
        memset(buf+rem+1, 0, 55-rem);
        padlen = 64;
    } else {
        memset(buf+rem+1, 0, 119-rem);
        padlen = 128;
    }
    uint64_t bitlen = (uint64_t)len * 8;
    for (int j=0;j<8;j++) buf[padlen-1-j] = (bitlen >> (8*j)) & 0xff;
    // compress padding block(s)
    for (size_t p=0; p<padlen; p+=64){
        uint32_t w[64];
        const uint8_t* blk = buf + p;
        for (int j=0;j<16;j++) w[j] = ((uint32_t)blk[j*4]<<24)|((uint32_t)blk[j*4+1]<<16)|((uint32_t)blk[j*4+2]<<8)|blk[j*4+3];
        for (int j=16;j<64;j++){
            uint32_t s0 = ROTR(w[j-15],7)^ROTR(w[j-15],18)^(w[j-15]>>3);
            uint32_t s1 = ROTR(w[j-2],17)^ROTR(w[j-2],19)^(w[j-2]>>10);
            w[j] = w[j-16]+s0+w[j-7]+s1;
        }
        uint32_t wk[64];
        for (int j=0;j<64;j++) wk[j] = w[j] + K[j];
        compress(s, wk);
    }
    for (int j=0;j<8;j++){ out[4*j]=(s[j]>>24)&0xff; out[4*j+1]=(s[j]>>16)&0xff; out[4*j+2]=(s[j]>>8)&0xff; out[4*j+3]=s[j]&0xff; }
}
EOF
