#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/evp.h>
void sha256_fast(const uint8_t* data, size_t len, uint8_t out[32]);
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }
int main(){
    size_t n = 20000*1024;
    uint8_t* data = malloc(n);
    srand(42);
    for (size_t i=0;i<n;i++) data[i]=rand()&0xff;
    uint8_t out[32], ref[32];
    unsigned int outlen;
    EVP_Digest(data,n,ref,&outlen,EVP_sha256(),NULL);
    sha256_fast(data,n,out);
    printf("match=%d\n", memcmp(out,ref,32)==0);
    for(int i=0;i<3;i++){ sha256_fast(data,n,out); }
    double t0=now();
    int N=100;
    for(int i=0;i<N;i++){ sha256_fast(data,n,out); }
    double t1=now();
    printf("fast per: %.6f s (%.1f MB/s)\n", (t1-t0)/N, n/((t1-t0)/N)/1e6);
    // openssl
    for(int i=0;i<3;i++){ EVP_Digest(data,n,ref,&outlen,EVP_sha256(),NULL); }
    t0=now();
    for(int i=0;i<N;i++){ EVP_Digest(data,n,ref,&outlen,EVP_sha256(),NULL); }
    t1=now();
    printf("openssl per: %.6f s (%.1f MB/s)\n", (t1-t0)/N, n/((t1-t0)/N)/1e6);
    return 0;
}
